/**
 * The Fluxa schema, as TypeScript.
 *
 * Hand-written rather than generated by `supabase gen types`, for the same
 * reason `config/flare.ts` is a hand-maintained mirror: there is no Supabase
 * project to generate against yet, and a generated file would encode the
 * generator's opinions about NUMERIC (see `Numeric` below) without the comment
 * explaining why they are dangerous here.
 *
 * `services/src/schema/rpc.ts` holds the indexer's *write* surface and points at
 * this file for the full type. The enum unions are duplicated across the two
 * workspaces on purpose — they install independently, so a shared package would
 * have to be published or path-linked to be importable. The migrations in
 * `database/migrations/` are the single source of truth for both copies.
 *
 * ## Insert and Update mirror the GRANTs, not the columns
 *
 * 0002 revokes INSERT and UPDATE on `invoices` wholesale and re-grants them on a
 * narrow column list, because RLS filters rows and cannot say "this column may
 * not change". The Insert and Update types below list exactly those granted
 * columns and nothing else, so writing `payment_tx_hash` from the browser is a
 * compile error rather than a runtime 403. The type system is doing the same job
 * as the grant, one layer earlier.
 */

// ---------------------------------------------------------------------------
// Enums — every one of these is a Postgres enum from 0001.
// ---------------------------------------------------------------------------

/** `invoice_status`. DRAFT and OPEN have no on-chain twin. */
export type InvoiceStatus =
  | 'DRAFT'
  | 'OPEN'
  | 'PENDING'
  | 'PAID'
  | 'SETTLED'
  | 'EXPIRED'
  | 'CANCELLED';

/** `payment_rail`. A is an observed ERC-20 transfer; B is an FDC-attested XRPL payment. */
export type PaymentRail = 'FLARE_ERC20' | 'XRPL_NATIVE';

/** `asset_symbol`. All three are 6-decimal; XRP is XRPL-native. */
export type AssetSymbol = 'FXRP' | 'USDT0' | 'XRP';

/** `attestation_status`. NOT_REQUIRED for Rail A, which needs no attestation. */
export type AttestationStatus =
  | 'NOT_REQUIRED'
  | 'PREPARING'
  | 'SUBMITTED'
  | 'FINALIZED'
  | 'VERIFIED'
  | 'FAILED';

/**
 * A Postgres NUMERIC as it arrives over the wire.
 *
 * Deliberately not `number`, which is what `supabase gen types` would have
 * produced. `token_amount` and `amount_units` are NUMERIC(78, 0) — uint256 base
 * units — and PostgREST serialises NUMERIC through Postgres `to_json`, which
 * emits an unquoted JSON literal. `JSON.parse` turns that into an IEEE double,
 * so any value above 2^53 comes back silently wrong.
 *
 * Typed as the union because which one arrives is a property of the PostgREST
 * version, not of this code, and being wrong about it should not compile. Every
 * read goes through `toBigInt`/`toDecimalString` in `lib/db/numeric.ts`, which
 * accept both and refuse a value that has already lost precision. Writes are
 * always strings — a string goes into NUMERIC unchanged.
 */
export type Numeric = string | number;

/** A Postgres `bigint`, which has the same JSON-precision problem as NUMERIC. */
export type Int8 = string | number;

// ---------------------------------------------------------------------------
// Rows
// ---------------------------------------------------------------------------

export type MerchantRow = {
  id: string;
  wallet_address: string;
  auth_user_id: string | null;
  display_name: string | null;
  email: string | null;
  settlement_asset: AssetSymbol;
  /** Payout destination. Falls back to `wallet_address` when null. */
  settlement_address: string | null;
  created_at: string;
  updated_at: string;
};

export type InvoiceRow = {
  id: string;
  merchant_id: string;
  customer_address: string | null;

  title: string;
  description: string | null;
  currency_code: string;

  /** The merchant's price. NUMERIC(20, 6). */
  usd_amount: Numeric;
  /** Base units of `token_symbol`, frozen at the first FTSO snapshot. */
  token_amount: Numeric | null;
  token_symbol: AssetSymbol;

  /** Raw FTSOv2 value — divide by 10^price_decimals. Never already divided. */
  price_usd: Numeric | null;
  /** That feed's own exponent: 6 for XRP/USD, 8 for FLR/USD. */
  price_decimals: number | null;
  price_timestamp: string | null;

  contract_version: number;
  accepted_payment_assets: AssetSymbol[];
  settlement_token_symbol: AssetSymbol;

  status: InvoiceStatus;
  due_at: string;
  paid_at: string | null;
  settled_at: string | null;
  expires_at: string | null;

  /** The bytes32 the contract emits in InvoiceCreated. Set once, by 0004. */
  invoice_reference: string | null;
  onchain_invoice_id: string | null;
  payment_tx_hash: string | null;
  rail: PaymentRail;

  discount_percent: Numeric;
  total_with_discount: Numeric | null;

  // Settlement evidence, added in 0003. Service-role only by omission from the
  // 0002 grant lists — the same reasoning as payment_tx_hash.
  settlement_tx_hash: string | null;
  /** May differ from `token_symbol`: pay FXRP, settle USDT0. */
  settled_token_symbol: AssetSymbol | null;
  settled_amount_units: Numeric | null;
  settled_to_address: string | null;

  // The price the payout was computed at, added in 0004. Not the same number as
  // `price_usd`, which is the quote the invoice was issued at.
  settlement_price_usd: Numeric | null;
  settlement_price_decimals: number | null;
  settlement_price_timestamp: string | null;

  created_at: string;
  updated_at: string;
};

export type PaymentEventRow = {
  id: Int8;
  invoice_id: string;

  rail: PaymentRail;
  tx_hash: string | null;
  block_number: Int8 | null;
  /** Position within the transaction. Part of the idempotency key, from 0003. */
  log_index: number;

  amount_units: Numeric;
  token_symbol: AssetSymbol;
  /** Coston2 addresses are 0x-hex, XRPL accounts are base58. Unconstrained. */
  payer_address: string;

  attestation_status: AttestationStatus;
  attestation_type: string | null;
  voting_round_id: Int8 | null;
  attestation_request_id: string | null;

  created_at: string;
};

// ---------------------------------------------------------------------------
// Writes, narrowed to the 0002 column grants
// ---------------------------------------------------------------------------

/**
 * What `authenticated` may INSERT into `invoices`.
 *
 * Exactly the 0002 `grant insert` list. A client supplies an invoice's terms,
 * never its outcome: `token_amount` and the FTSO snapshot are absent because
 * they are written by `prepare_invoice_for_chain`, and every evidence column is
 * absent because only the indexer writes those.
 */
export type InvoiceInsert = {
  merchant_id: string;
  title: string;
  usd_amount: string;
  token_symbol: AssetSymbol;
  due_at: string;
  customer_address?: string | null;
  description?: string | null;
  currency_code?: string;
  status?: Extract<InvoiceStatus, 'DRAFT' | 'OPEN'>;
  rail?: PaymentRail;
  discount_percent?: string;
  total_with_discount?: string | null;
  accepted_payment_assets: AssetSymbol[];
  settlement_token_symbol: AssetSymbol;
};

/**
 * What `authenticated` may UPDATE on `invoices`.
 *
 * The 0002 `grant update` list. Note `status` is granted but the policy's WITH
 * CHECK narrows it to DRAFT, OPEN and CANCELLED — a merchant may cancel or
 * publish their invoice, never mark it paid.
 */
export type InvoiceUpdate = {
  customer_address?: string | null;
  title?: string;
  description?: string | null;
  usd_amount?: string;
  token_symbol?: AssetSymbol;
  status?: Extract<InvoiceStatus, 'DRAFT' | 'OPEN' | 'CANCELLED'>;
  due_at?: string;
  rail?: PaymentRail;
  discount_percent?: string;
  total_with_discount?: string | null;
  accepted_payment_assets?: AssetSymbol[];
  settlement_token_symbol?: AssetSymbol;
};

/**
 * Merchant self-registration. 0002 revokes no columns on `merchants`, so the
 * grant is the table default and RLS does the work: `auth_user_id` must equal
 * `auth.uid()`, which is what stops a session claiming another wallet.
 */
export type MerchantInsert = {
  wallet_address: string;
  auth_user_id: string;
  display_name?: string | null;
  email?: string | null;
  settlement_asset?: AssetSymbol;
  settlement_address?: string | null;
};

export type MerchantUpdate = {
  display_name?: string | null;
  email?: string | null;
  settlement_asset?: AssetSymbol;
  settlement_address?: string | null;
};

// ---------------------------------------------------------------------------
// Function return shapes
// ---------------------------------------------------------------------------

/**
 * One row of `get_public_invoice(uuid)` — the payer's view, as redefined in 0004.
 *
 * Narrower than `InvoiceRow` on purpose: no merchant email, no internal ids, no
 * `merchant_id`. It is also the only way `anon` reads an invoice at all, since
 * 0002 gives `anon` no SELECT policy on any table.
 */
export type PublicInvoice = {
  id: string;
  title: string;
  description: string | null;
  usd_amount: Numeric;
  token_amount: Numeric | null;
  token_symbol: AssetSymbol;
  price_usd: Numeric | null;
  price_decimals: number | null;
  price_timestamp: string | null;
  contract_version: number;
  accepted_payment_assets: AssetSymbol[];
  settlement_token_symbol: AssetSymbol;
  status: InvoiceStatus;
  rail: PaymentRail;
  due_at: string;
  paid_at: string | null;
  settled_at: string | null;
  invoice_reference: string | null;
  onchain_invoice_id: string | null;
  payment_tx_hash: string | null;
  settlement_tx_hash: string | null;
  discount_percent: Numeric;
  total_with_discount: Numeric | null;
  merchant_name: string | null;
  /** Wallet that created the on-chain invoice; used to prevent self-payment. */
  merchant_address: string;
  settlement_asset: AssetSymbol;
  created_at: string;
};

/** One row of `get_public_invoice_events(uuid)`. */
export type PublicInvoiceEvent = {
  rail: PaymentRail;
  tx_hash: string | null;
  block_number: Int8 | null;
  amount_units: Numeric;
  token_symbol: AssetSymbol;
  payer_address: string;
  attestation_status: AttestationStatus;
  voting_round_id: Int8 | null;
  created_at: string;
};

/** Arguments to `prepare_invoice_for_chain` (0004). Numerics as strings. */
export type PrepareInvoiceArgs = {
  p_invoice_id: string;
  p_token_amount: string;
  p_token_symbol: AssetSymbol;
  p_price_usd: string;
  p_price_decimals: number;
  p_price_timestamp: string;
};

export type PrepareInvoiceV2Args = { p_invoice_id: string };

// ---------------------------------------------------------------------------
// The Database type the Supabase client is generic over
// ---------------------------------------------------------------------------

/**
 * `sync_state` is absent, and so are `record_payment_event`, `record_settlement`
 * and `advance_sync_cursor`. All four are revoked from `anon` and
 * `authenticated` in 0003, so naming them here would only make it possible to
 * write a call the database is guaranteed to refuse. The client's type describes
 * the client's reach.
 */
export type Database = {
  public: {
    Tables: {
      merchants: {
        Row: MerchantRow;
        Insert: MerchantInsert;
        Update: MerchantUpdate;
        Relationships: [];
      };
      invoices: {
        Row: InvoiceRow;
        Insert: InvoiceInsert;
        Update: InvoiceUpdate;
        Relationships: [
          {
            foreignKeyName: 'invoices_merchant_id_fkey';
            columns: ['merchant_id'];
            referencedRelation: 'merchants';
            referencedColumns: ['id'];
            isOneToOne: false;
          },
        ];
      };
      payment_events: {
        /** Read-only to every client role: 0002 revokes insert, update, delete. */
        Row: PaymentEventRow;
        Insert: never;
        Update: never;
        Relationships: [
          {
            foreignKeyName: 'payment_events_invoice_id_fkey';
            columns: ['invoice_id'];
            referencedRelation: 'invoices';
            referencedColumns: ['id'];
            isOneToOne: false;
          },
        ];
      };
    };
    Views: Record<never, never>;
    Functions: {
      current_merchant_id: {
        Args: Record<never, never>;
        Returns: string | null;
      };
      get_public_invoice: {
        Args: { p_invoice_id: string };
        Returns: PublicInvoice[];
      };
      get_public_invoice_events: {
        Args: { p_invoice_id: string };
        Returns: PublicInvoiceEvent[];
      };
      prepare_invoice_for_chain: {
        Args: PrepareInvoiceArgs;
        /** The payment reference to publish on-chain. */
        Returns: string;
      };
      prepare_invoice_v2: {
        Args: PrepareInvoiceV2Args;
        Returns: string;
      };
    };
    Enums: {
      invoice_status: InvoiceStatus;
      payment_rail: PaymentRail;
      asset_symbol: AssetSymbol;
      attestation_status: AttestationStatus;
    };
    CompositeTypes: Record<never, never>;
  };
};
